import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { AIFooterProps } from "./ai-footer.types";
import { AIFooterClasses, StyledAIFooter } from "./ai-footer.styles";

export const AIFooter = forwardRef<HTMLDivElement, AIFooterProps>(
  ({ className, children, variant = "default", ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(AIFooterClasses.root, className);

    return (
      <StyledAIFooter
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledAIFooter>
    );
  },
);

AIFooter.displayName = "AI.Footer";
